static void kickpi_dump_reset_status(void)
{
  uint32_t st = getreg32(RK3576_CRU_ADDR + 0x0c04);

  syslog(LOG_INFO,
         "复位状态: GLB_RST_ST=0x%08" PRIx32 "（bit5/6/11-15 任一置位=看门狗）\n",
         st);
}

void board_late_initialize(void)
{
  kickpi_dump_reset_status();

