      if (g_bootmode == RK3576_REBOOT_WATCHDOG)
        {
          putreg32(RK3576_REBOOT_NORMAL,
                   RK3576_PMU0_GRF_ADDR + RK3576_REBOOT_MODE_OFF);
        }
    }

  return g_bootmode;
}

bool rk3576_bootmode_is_watchdog(void)
{
  return rk3576_bootmode_latch() == RK3576_REBOOT_WATCHDOG;
}

